package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import android.widget.*;import java.util.*;
public class SectorGuideActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);String s=getIntent().getStringExtra("sector");DataNormalizer.Sector sec;try{sec=DataNormalizer.Sector.valueOf(s);}catch(Exception e){sec=DataNormalizer.Sector.METAMUSIQUE;}LinearLayout r=Ui.root(this);r.addView(Ui.text(this,sec.label,28,true));r.addView(Ui.text(this,"Référentiel de préparation. L’application distingue maintenant les éléments confirmés par une source publique des profils de travail qui doivent encore être validés avec la documentation sectorielle complète.",13,false));
 LinearLayout status=Ui.panel(this);status.addView(Ui.text(this,"Niveau de preuve intégré",20,true));if(sec==DataNormalizer.Sector.METAMUSIQUE){status.addView(Ui.text(this,"CONFIRMÉ PARTIELLEMENT PAR SOURCE PUBLIQUE",15,true));status.addView(Ui.text(this,"Le référentiel public MétaMusique confirme notamment : titre, durée, ISRC, œuvre associée, producteur, studio/date d’enregistrement, interprètes, contributeurs techniques, langue/paroles, genres/tags et financement public. Le profil de l’application reste volontairement plus simple tant que toutes les règles normatives ne sont pas intégrées.",13,false));Button ref=Ui.secondary(this,"Ouvrir le référentiel MétaMusique");ref.setOnClickListener(v->open("https://metamusique.ca/referentiel/"));status.addView(ref);Button doc=Ui.secondary(this,"Informations à documenter — MétaMusique");doc.setOnClickListener(v->open("https://metamusique.ca/documentez-vos-enregistrements-sonores/"));status.addView(doc);}else{status.addView(Ui.text(this,"PROFIL DE TRAVAIL — VALIDATION SECTORIELLE REQUISE",15,true));status.addView(Ui.text(this,"Le Ministère reconnaît cette norme dans le Programme de soutien à la standardisation des données, mais l’application ne présente pas encore la totalité de son schéma officiel champ par champ. Aucun champ n’est donc étiqueté « obligatoire » sans source normative vérifiée.",13,false));}r.addView(status);
 LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,"Champs de travail actuellement intégrés",20,true));for(String f:sec.suggestedFields)p.addView(Ui.text(this,"• "+f,16,false));r.addView(p);
 LinearLayout gov=Ui.panel(this);gov.addView(Ui.text(this,"Référence du programme",20,true));gov.addView(Ui.text(this,"Les cinq normes reconnues par le Programme sont : MétaMusique, Arts de la scène, Cinéma, Livre (éditeurs) et Exposition dans un contexte muséal. Le projet doit être une mise à niveau concrète d’une base de données et prévoir un calendrier d’au plus 12 mois.",13,false));Button program=Ui.primary(this,"Ouvrir le programme officiel du Québec");program.setOnClickListener(v->open("https://www.quebec.ca/culture/aide-financiere/aide-aux-projets-appel/soutien-standardisation-donnees/appel-projets-soutien-standardisation-donnees"));gov.addView(program);r.addView(gov);
 r.addView(Ui.text(this,"Principe de sécurité des données : l’application ne doit jamais transformer un profil de travail en « norme officielle » sans preuve. La validation humaine et la documentation sectorielle demeurent nécessaires avant une soumission ou une publication.",13,false));setContentView(Ui.wrap(this,r));}
 private void open(String u){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception ignored){}}
}
